        url = f"{DATABRICKS_HOST}/api/2.0/clusters/create"
        payload = {
            "cluster_name": f"{PREFIX}_cluster",
            "spark_version": "13.3.x-scala2.12",
            "node_type_id": "i3.xlarge",
            "num_workers": 1,
            "autotermination_minutes": 30
        }

        response = requests.post(url, headers=headers, data=json.dumps(payload))
        if response.status_code != 200:
            raise Exception(f"Failed to create cluster: {response.text}")

        cluster_id = response.json()["cluster_id"]
        print(f"Created cluster: {cluster_id}")

        # Wait for cluster to start
        url = f"{DATABRICKS_HOST}/api/2.0/clusters/get"
        payload = {
            "cluster_id": cluster_id
        }

        while True:
            response = requests.get(url, headers=headers, params=payload)
            if response.status_code != 200:
                raise Exception(f"Failed to get cluster status: {response.text}")

            cluster_state = response.json().get("state", "")
            if cluster_state == "RUNNING":
                break
            elif cluster_state in ["TERMINATED", "ERROR"]:
                raise Exception(f"Cluster failed to start: {cluster_state}")

            time.sleep(10)

        return cluster_id
    except Exception as e:
        print(f"Error getting or creating cluster: {e}")
        return None

# Submit the job
def submit_job(workspace_path, cluster_id):
    try:
        # Create the job
        url = f"{DATABRICKS_HOST}/api/2.0/jobs/create"
        payload = {
            "name": f"{PREFIX}_churn_training_job",
            "tasks": [
                {
                    "task_key": "create_training_dataset",
                    "spark_python_task": {
                        "python_file": workspace_path,
                        "parameters": [f"--schema={SCHEMA_NAME}"]
                    },
                    "existing_cluster_id": cluster_id
                }
            ],
            "email_notifications": {
                "on_success": [],
                "on_failure": []
            },
            "timeout_seconds": 3600
        }

        response = requests.post(url, headers=headers, data=json.dumps(payload))
        if response.status_code != 200:
            raise Exception(f"Failed to create job: {response.text}")

        job_id = response.json()["job_id"]
        print(f"Created job: {job_id}")

        # Run the job
        url = f"{DATABRICKS_HOST}/api/2.0/jobs/run-now"
        payload = {
            "job_id": job_id
        }

        response = requests.post(url, headers=headers, data=json.dumps(payload))
        if response.status_code != 200:
            raise Exception(f"Failed to run job: {response.text}")

        run_id = response.json()["run_id"]
        print(f"Started job run: {run_id}")

        # Wait for completion
        url = f"{DATABRICKS_HOST}/api/2.0/jobs/runs/get"
        payload = {
            "run_id": run_id
        }

        while True:
            response = requests.get(url, headers=headers, params=payload)
            if response.status_code != 200:
                raise Exception(f"Failed to get run status: {response.text}")

            run_state = response.json().get("state", {})
            if run_state.get("life_cycle_state") in ["TERMINATED", "SKIPPED", "INTERNAL_ERROR"]:
                break

            time.sleep(10)

        if run_state.get("result_state") == "SUCCESS":
            print("Job completed successfully.")
        else:
            print(f"Job failed: {run_state}")

    except Exception as e:
        print(f"Error submitting job: {e}")

